#!/usr/bin/env bash
# Copy emscripten artifacts next to tsc output so published imports resolve.
set -euo pipefail
JS_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SRC="$JS_ROOT/src/wasm"
DST="$JS_ROOT/dist/wasm"
mkdir -p "$DST"
REV="$(shasum -a 256 "$SRC/xpict_core.wasm" | awk '{print substr($1,1,12)}')"
cat > "$SRC/rev.ts" <<EOF
/** Generated by copy-wasm.sh — do not edit. */
export const XPICT_WASM_REV = "${REV}";
EOF
cp -a "$SRC"/xpict_core.js "$SRC"/xpict_core.d.ts "$SRC"/xpict_core.wasm "$DST"/
echo "Copied wasm → dist/wasm (rev ${REV})"
